-- ============================================
-- BM Electronics Stock - Full Import
-- Source: BM Electronics Stock.xlsx
-- Total items: 391
-- Store: BM Electronic (a0000000-0000-0000-0000-000000000003)
-- Run this in Supabase SQL Editor
-- ============================================

-- 1. Clear old stock for BM Electronic only
DELETE FROM public.stock WHERE store_id = 'a0000000-0000-0000-0000-000000000003';
DELETE FROM public.stock_lots WHERE store_id = 'a0000000-0000-0000-0000-000000000003';

-- 2. Insert stock items

-- 3. Insert stock lots (one lot per item for FIFO sales)
-- Reset lot sequence first
SELECT setval('public.lot_no_seq', (SELECT COALESCE(MAX(CAST(SUBSTRING(lot_no FROM 5) AS integer)), 0) FROM public.stock_lots));


-- 4. Reset sequences (global — set to max across ALL stores)
SELECT setval('public.stock_code_seq', GREATEST(1, (SELECT COALESCE(MAX(CAST(code AS integer)), 0) FROM public.stock)));
SELECT setval('public.lot_no_seq', GREATEST(1, (SELECT COALESCE(MAX(CAST(SUBSTRING(lot_no FROM 5) AS integer)), 0) FROM public.stock_lots)));
